def largest_prime_factor(n: int):
    """Return the largest prime factor of n. Assume n > 1 and is not a prime."""

    # Start with the smallest possible divisor (2)
    i = 2

    while i * i <= n:
        # While i divides n, divide it out repeatedly to remove all factors of i
        while n % i == 0:
            n //= i

        # Move to the next candidate factor
        if i == 2:
            i += 1
        else:
            i += 2  # Skip even numbers after 2

    # If n is still greater than 1, then it's a prime number itself (the largest)
    return n

