def words_in_sentence(sentence):
    """
    Returns a string containing only the words from the original sentence
    whose lengths are prime numbers, preserving order.
    """
    # Split into words (strip any surrounding spaces)
    words = [w.strip() for w in sentence.split()]

    filtered_words = []
    for word in words:
        if is_prime(len(word)):
            filtered_words.append(word)

    return " ".join(filtered_words)


